insert into public.openings (name, address, neighbourhood, status, opened_label, sort_on, blurb, source_name, source_url, pub_id) values
('Moylett''s', '181 Clarence Road, E5', 'Clapton', 'open', 'Opened late 2025', '2025-12-01', 'Family-run Irish pub in an old Victorian boozer. Time Out''s favourite new pub of 2026.', 'Time Out', 'https://www.timeout.com/london/news/best-new-pub-london-2026-moyletts-110226', (select id from public.pubs where city = 'London' and lower(replace(name, '’', '''')) = lower('Moylett''s') and address ilike '%Clarence Road%' limit 1)),
('The Black Cap', '171 Camden High Street, NW1 7JY', 'Camden', 'open', 'Reopened March 2026', '2026-03-01', 'The Camden landmark is back, with drag bingo, karaoke and rooms upstairs.', 'Londonist', 'https://londonist.com/london/drink/london-s-best-new-pubs-of-2026', (select id from public.pubs where city = 'London' and lower(replace(name, '’', '''')) = lower('The Black Cap') and address ilike '%Camden High%' limit 1)),
('The Black Eel', '41 Kingsland High Street, E8 2JP', 'Dalston', 'open', 'Opened 2026', '2026-02-01', 'In a former pie-and-mash shop, with a games room and a big garden out back.', 'Londonist', 'https://londonist.com/london/drink/london-s-best-new-pubs-of-2026', (select id from public.pubs where city = 'London' and lower(replace(name, '’', '''')) = lower('The Black Eel') and address ilike '%Kingsland High%' limit 1)),
('Golden Tooth', '79 Green Lanes, N16 9BU', 'Stoke Newington', 'open', 'Opened 2026', '2026-02-01', 'From chef Matthew Scott, formerly of Papi in London Fields. Keg only.', 'Londonist', 'https://londonist.com/london/drink/london-s-best-new-pubs-of-2026', (select id from public.pubs where city = 'London' and lower(replace(name, '’', '''')) = lower('Golden Tooth') and address ilike '%Green Lanes%' limit 1)),
('Hand and Marigold', '244 Bermondsey Street, SE1 3UH', 'Bermondsey', 'open', 'Opened 2026', '2026-02-01', 'Independent, sister to the Trafalgar in Merton, with rotating cask from small breweries.', 'Londonist', 'https://londonist.com/london/drink/london-s-best-new-pubs-of-2026', (select id from public.pubs where city = 'London' and lower(replace(name, '’', '''')) = lower('Hand and Marigold') and address ilike '%Bermondsey Street%' limit 1)),
('The Horsemen', '1 Broadgate, EC2M 2QS', 'Broadgate', 'open', 'Opened 2026', '2026-02-01', 'An American-Irish pub, and the only proper pub in Broadgate.', 'Londonist', 'https://londonist.com/london/drink/london-s-best-new-pubs-of-2026', (select id from public.pubs where city = 'London' and lower(replace(name, '’', '''')) = lower('The Horsemen') and address ilike '%Broadgate%' limit 1)),
('Mary Wollstonecraft', '181 Stoke Newington Church Street, N16 0UL', 'Stoke Newington', 'open', 'Opened 2026', '2026-02-01', 'Eight cask lines and a wide keg list, mostly from small breweries.', 'Londonist', 'https://londonist.com/london/drink/london-s-best-new-pubs-of-2026', (select id from public.pubs where city = 'London' and lower(replace(name, '’', '''')) = lower('Mary Wollstonecraft') and address ilike '%Church Street%' limit 1)),
