-- New openings, gathered by hand from Time Out, Londonist and Hot Dinners on 3 November 2026.
-- Facts only (name, address, date), in our own words, each linked to its source.
on conflict (name, city) do update set address = excluded.address, neighbourhood = excluded.neighbourhood, status = excluded.status,
  opened_label = excluded.opened_label, sort_on = excluded.sort_on, blurb = excluded.blurb, source_name = excluded.source_name,
  source_url = excluded.source_url, pub_id = coalesce(excluded.pub_id, openings.pub_id);
